import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

const API_KEY = "AIzaSyAycjPVxkbcJFfOSJyTp8oBUsONgK7lY1k"; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [filtreKategori, setFiltreKategori] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  const [seciliMekan, setSeciliMekan] = useState(null);
  const [aiCevap, setAiCevap] = useState("");
  const [loading, setLoading] = useState(false);

  // 1. Veriyi Çek
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(data))
      .catch(err => console.error("API Hatası:", err));
  }, []);

  // 2. HESAPLAMALAR (Süre + Bütçe)
  const toplamSure = favoriler.reduce((toplam, m) => toplam + (parseInt(m.sure) || 0), 0);
  const toplamButce = favoriler.reduce((toplam, m) => toplam + (parseInt(m.ucret) || 0), 0);

  const saat = Math.floor(toplamSure / 60);
  const dakika = toplamSure % 60;

  // 3. FONKSİYONLAR
  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id == mekan.id);
    if (varMi) {
      setFavoriler(favoriler.filter(f => f.id != mekan.id));
    } else {
      setFavoriler([...favoriler, mekan]);
    }
  };

  // 🚀 ÖZELLİK: Akıllı Sıralama (Bölgeye Göre Grupla)
  const rotayiSirala = () => {
    const sirali = [...favoriler].sort((a, b) => a.bolge.localeCompare(b.bolge));
    setFavoriler(sirali);
    alert("Rota bölgelere göre optimize edildi! 🗺️");
  };

  // 🚀 ÖZELLİK: PDF Çıktısı (Yazdırma Ekranı)
  const pdfIndir = () => {
    if(favoriler.length === 0) return alert("Listen boş!");
    window.print(); // Tarayıcının yazdırma özelliğini tetikler
  };

  const askAI = async (mekan) => {
    if(!API_KEY || API_KEY.includes("BURAYA")) { alert("Lütfen API Key yapıştırın!"); return; }
    setLoading(true); setAiCevap("");
    try {
      const genAI = new GoogleGenerativeAI(API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-pro"});
      const prompt = `Antalya'daki "${mekan.ad}" hakkında turistler için 2 kısa, ilgi çekici cümle kur.`;
      const result = await model.generateContent(prompt);
      const response = await result.response;
      setAiCevap(response.text());
    } catch (error) { setAiCevap("Hata oluştu."); } 
    finally { setLoading(false); }
  };

  const filtrelenmisMekanlar = mekanlar.filter(m => {
    const katUygun = filtreKategori === 'Hepsi' || m.kategori === filtreKategori;
    const sureUygun = !maxSure || m.sure <= parseInt(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="app-container">
      <style>{`
        :root { --primary: #0aa1a1; --accent: #a9e6dd; --bg: #f3f4f6; --text: #1f2937; }

        body { margin: 0; font-family: 'Segoe UI', sans-serif; background: linear-gradient(135deg, #e0f7fa 0%, #e0f2f1 100%); color: var(--text); min-height: 100vh; }
        .app-container { max-width: 1200px; margin: 0 auto; padding: 40px 20px; }

        /* Header Stats */
        .stats-bar {
          display: flex; justify-content: space-between; align-items: center;
          background: linear-gradient(135deg, var(--primary), #1f6f9c);
          color: white; padding: 25px 40px; border-radius: 20px;
          box-shadow: 0 10px 25px -5px rgba(30, 58, 138, 0.25);
          flex-wrap: wrap; gap: 20px;
        }
        .stat-group { display: flex; gap: 40px; }
        .stat-item h2 { margin: 0; font-size: 28px; font-weight: 700; }
        .stat-item p { margin: 0; opacity: 0.8; font-size: 13px; text-transform: uppercase; letter-spacing: 1px; }

        /* Controls */
        .controls { display: flex; gap: 15px; margin-top: 30px; flex-wrap: wrap; align-items: center; }
        .input-styled { padding: 12px 20px; border: 2px solid #e5e7eb; border-radius: 12px; outline: none; }
        .btn-tool { padding: 12px 20px; border-radius: 12px; border: none; cursor: pointer; font-weight: 600; background: white; color: var(--primary); box-shadow: 0 2px 5px rgba(0,0,0,0.1); transition: all 0.2s; }
        .btn-tool:hover { transform: translateY(-2px); box-shadow: 0 5px 10px rgba(0,0,0,0.1); }

        /* Grid & Cards */
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 30px; margin-top: 40px; }
        .card { background: white; border-radius: 20px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); transition: transform 0.3s ease; display: flex; flex-direction: column; position: relative; }
        .card:hover { transform: translateY(-8px); box-shadow: 0 20px 25px -5px rgba(0,0,0,0.1); }

        .card-img-wrap { height: 200px; position: relative; cursor: pointer; }
        .card-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
        .card-img-wrap:hover .card-img { transform: scale(1.1); }

        .badge { position: absolute; top: 15px; right: 15px; background: rgba(255,255,255,0.95); color: var(--primary); padding: 4px 10px; border-radius: 20px; font-size: 12px; font-weight: bold; z-index: 2; }
        /* 🌦️ HAVA DURUMU BADGE */
        .weather-badge { position: absolute; top: 15px; left: 15px; background: rgba(0,0,0,0.6); color: #fbbf24; padding: 4px 10px; border-radius: 20px; font-size: 12px; font-weight: bold; z-index: 2; }

        .card-body { padding: 20px; flex-grow: 1; position: relative; z-index: 1; background: white; }
        .card-info { display: flex; justify-content: space-between; color: #6b7280; font-size: 14px; margin-top: 5px; }
        .price-tag { color: #10b981; font-weight: bold; }

        .hover-info { position: absolute; top:0; left:0; right:0; bottom:0; background: rgba(10,161,161,0.9); color: white; display: flex; align-items: center; justify-content: center; text-align: center; padding: 20px; opacity: 0; transition: 0.3s; font-weight: 500; }
        .card-img-wrap:hover .hover-info { opacity: 1; }

        .card-actions { padding: 15px; background: #f9fafb; display: flex; gap: 10px; border-top: 1px solid #f3f4f6; }
        .btn { flex: 1; padding: 10px; border: none; border-radius: 8px; cursor: pointer; font-weight: 600; }
        .btn-primary { background: var(--primary); color: white; }
        .btn-active { background: #ef4444; color: white; }
        .btn-outline { background: white; border: 1px solid #ddd; }

        /* 🖨️ YAZDIRMA MODU (PDF İÇİN) */
        @media print {
          .controls, .card-actions, .header-intro, .btn-tool { display: none !important; }
          .app-container { max-width: 100%; padding: 0; }
          .grid { display: block; }
          .card { page-break-inside: avoid; border: 1px solid #ddd; margin-bottom: 20px; box-shadow: none; flex-direction: row; height: 120px; }
          .card-img-wrap { width: 150px; height: 100%; }
          .card-body { padding: 10px 20px; }
          body { background: white; }
          .stats-bar { background: #eee; color: black; box-shadow: none; border: 1px solid #ccc; }
          .stat-item h2 { font-size: 20px; }
        }
      `}</style>

      {/* --- HEADER --- */}
      <div className="header-section">
        <div className="stats-bar">
          <div className="stat-item header-intro">
            <p>Antalya Rota Planlayıcı</p>
            <h2>Gezilecek Yerler</h2>
          </div>

          <div className="stat-group">
            <div className="stat-item" style={{textAlign: 'right'}}>
              <p>Toplam Süre</p>
              <h2>{saat} sa {dakika} dk</h2>
            </div>
            {/* 💰 YENİ: BÜTÇE GÖSTERGESİ */}
            <div className="stat-item" style={{textAlign: 'right'}}>
              <p>Tahmini Bütçe</p>
              <h2 style={{color: '#a9e6dd'}}>{toplamButce} ₺</h2>
            </div>
          </div>
        </div>

        {/* --- KONTROLLER --- */}
        <div className="controls">
          <select className="input-styled" value={filtreKategori} onChange={(e) => setFiltreKategori(e.target.value)}>
            <option value="Hepsi">Tüm Kategoriler</option>
            <option value="Tarih">🏛 Tarih</option>
            <option value="Doğa">🌲 Doğa</option>
            <option value="Eğlence">🎢 Eğlence</option>
          </select>

          <input type="number" className="input-styled" placeholder="Maks. Süre (dk)" value={maxSure} onChange={(e) => setMaxSure(e.target.value)} style={{width: '120px'}} />

          {/* 🚀 YENİ BUTONLAR */}
          <button type="button" className="btn-tool" onClick={rotayiSirala}>🔄 Rotayı Düzenle</button>
          <button type="button" className="btn-tool" onClick={pdfIndir}>🖨️ PDF İndir</button>
        </div>
      </div>

      {/* --- LİSTE --- */}
      <div className="grid">
        {filtrelenmisMekanlar.map((mekan) => {
          const favorideMi = favoriler.some(f => f.id == mekan.id);

          return (
            <div key={mekan.id} className="card">
              <div className="card-img-wrap">
                <img src={mekan.resim} alt={mekan.ad} className="card-img" onError={(e) => {e.target.onerror=null; e.target.src="https://via.placeholder.com/300?text=Resim+Yok"}} />
                <span className="badge">{mekan.kategori}</span>
                {/* 🌦️ HAVA DURUMU */}
                <span className="weather-badge">{mekan.hava}</span>
                <div className="hover-info"><p>{mekan.aciklama}</p></div>
              </div>

              <div className="card-body">
                <h3 className="card-title">{mekan.ad}</h3>
                <div className="card-info">
                  <span>📍 {mekan.bolge}</span>
                  <span>⏱ {mekan.sure} dk</span>
                </div>
                <div className="card-info" style={{marginTop:'5px'}}>
                   {/* 💰 FİYAT ETİKETİ */}
                   <span className="price-tag">💵 {mekan.ucret === 0 ? "Ücretsiz" : `${mekan.ucret} ₺`}</span>
                </div>
              </div>

              <div className="card-actions">
                <button type="button" className="btn btn-outline" onClick={() => { setSeciliMekan(mekan); askAI(mekan); }}>✨ AI</button>
                <button type="button" className={`btn ${favorideMi ? 'btn-active' : 'btn-primary'}`} onClick={() => toggleFavori(mekan)}>
                  {favorideMi ? 'Çıkar' : 'Ekle +'}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* MODAL */}
      {seciliMekan && (
        <div style={{position:'fixed', top:0, left:0, right:0, bottom:0, background:'rgba(0,0,0,0.8)', display:'flex', alignItems:'center', justifyContent:'center', zIndex:1000}} onClick={() => setSeciliMekan(null)}>
          <div style={{background:'white', padding:'30px', borderRadius:'20px', maxWidth:'500px', width:'90%'}} onClick={e => e.stopPropagation()}>
            <h2 style={{marginTop:0}}>{seciliMekan.ad}</h2>
            <p>{seciliMekan.aciklama}</p>
            <div style={{background:'#f0fdfa', padding:'15px', borderRadius:'10px', marginTop:'15px', borderLeft:'4px solid #0aa1a1'}}>
              {loading ? "🤖 Yapay zeka düşünüyor..." : aiCevap || "Cevap bekleniyor..."}
            </div>
            <button type="button" className="btn btn-primary" style={{marginTop:'20px', width:'100%'}} onClick={() => setSeciliMekan(null)}>Kapat</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
